// d3d_trace.cpp - Call tracing for the statically linked XDK D3D library.
//
// Every D3D entry point from d3d_trace_list.inc (generated by
// tools/gen_d3d_trace.py) is overridden with a thin wrapper that counts calls
// and samples r3-r8/lr, then runs the original recompiled body. Used to map
// the anonymous D3D functions for the native renderer.
//
// --ao2_d3d_trace=true            enable
// --ao2_d3d_trace_every=600       dump one full frame every N swaps
// Output: d3d_trace.txt in the working directory.

#include <cstdio>
#include <map>
#include <mutex>
#include <vector>

#include <rex/cvar.h>
#include <rex/ppc.h>

REXCVAR_DEFINE_BOOL(ao2_d3d_trace, false, "Debug", "Trace XDK D3D entry points to d3d_trace.txt");
REXCVAR_DEFINE_INT32(ao2_d3d_trace_every, 600, "Debug", "D3D trace: dump one frame every N swaps");

namespace
{
  constexpr uint32_t kSwap = 0x82B23578;
  constexpr size_t kMaxSamples = 8;

  struct Sample
  {
    uint32_t lr;
    uint32_t r[6];
  };

  struct Stat
  {
    uint64_t total = 0;
    uint32_t frame = 0;
    std::vector<Sample> samples;
  };

  std::mutex g_mutex;
  std::map<uint32_t, Stat> g_stats;
  uint64_t g_frame = 0;
  bool g_capturing = false;
  FILE *g_out = nullptr;

  void Dump()
  {
    if (!g_out)
    {
      g_out = std::fopen("d3d_trace.txt", "w");
      if (!g_out)
      {
        return;
      }
    }
    std::fprintf(g_out, "=== frame %llu ===\n", static_cast<unsigned long long>(g_frame));
    for (auto &[addr, s] : g_stats)
    {
      if (!s.frame)
      {
        continue;
      }
      std::fprintf(g_out, "%08X calls=%u total=%llu\n", addr, s.frame,
                   static_cast<unsigned long long>(s.total));
      for (auto &x : s.samples)
      {
        std::fprintf(g_out, "    lr=%08X r3=%08X r4=%08X r5=%08X r6=%08X r7=%08X r8=%08X\n", x.lr,
                     x.r[0], x.r[1], x.r[2], x.r[3], x.r[4], x.r[5]);
      }
    }
    std::fprintf(g_out, "--- ever called:");
    for (auto &[addr, s] : g_stats)
    {
      std::fprintf(g_out, " %08X", addr);
    }
    std::fprintf(g_out, "\n");
    std::fflush(g_out);
  }

} // namespace

void D3DTraceEnter(uint32_t addr, PPCContext &ctx)
{
  {
    if (!REXCVAR_GET(ao2_d3d_trace))
    {
      return;
    }
    std::lock_guard lock(g_mutex);
    Stat &s = g_stats[addr];
    s.total++;
    s.frame++;
    if (g_capturing && s.samples.size() < kMaxSamples)
    {
      s.samples.push_back({static_cast<uint32_t>(ctx.lr),
                           {ctx.r3.u32, ctx.r4.u32, ctx.r5.u32, ctx.r6.u32, ctx.r7.u32, ctx.r8.u32}});
    }
    if (addr == kSwap)
    {
      ++g_frame;
      if (g_capturing)
      {
        Dump();
      }
      int every = REXCVAR_GET(ao2_d3d_trace_every);
      g_capturing = every > 0 && (g_frame % static_cast<uint64_t>(every)) == 0;
      for (auto &[a, st] : g_stats)
      {
        st.frame = 0;
        st.samples.clear();
      }
    }
  }
}

// The wrappers run on every D3D call of the rendering thread: with tracing
// off they are a flag test and a tail jump to the original body.
#define D3D_TRACE_HOOK(addr)                                   \
  extern "C" REX_FUNC(__imp__sub_##addr);                      \
  extern "C" REX_FUNC(sub_##addr)                              \
  {                                                            \
    if (REXCVAR_GET(ao2_d3d_trace)) [[unlikely]]               \
    {                                                          \
      D3DTraceEnter(0x##addr, ctx);                            \
    }                                                          \
    [[clang::musttail]] return __imp__sub_##addr(ctx, base);   \
  }

#include "d3d_trace_list.inc"
